LEARN.course({id:"blues",family:"Blues",name:"Electric blues: Chicago and Texas",tagline:"Twelve bars, a shuffle and a guitar that answers the singer.",level:"Intermediate",era:"1940s to today",artists:["Muddy Waters","B.B. King","Albert King","Freddie King","Buddy Guy","Stevie Ray Vaughan","Albert Collins"],listen:["Muddy Waters – Hoochie Coochie Man","B.B. King – Sweet Little Angel (Live at the Regal)","Freddie King – Hide Away","Albert King – Born Under a Bad Sign","Albert Collins – Frosty","Stevie Ray Vaughan and Double Trouble – Pride and Joy"],key:"A major",bpm:100,meter:"4/4",techniques:["bends","vibrato","palm-muting"],sources:[{id:"s1",title:"Electric blues",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Electric_blues",kind:"encyclopedia"},{id:"s2",title:"Chicago blues",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Chicago_blues",kind:"encyclopedia"},{id:"s3",title:"Twelve-bar blues",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Twelve-bar_blues",kind:"encyclopedia"},{id:"s4",title:"Add a Blues Flavor to Your Rhythm with Simple Chord Embellishments",author:"Jeffrey Pepper Rodgers",site:"Acoustic Guitar",year:2024,url:"https://acousticguitar.com/add-a-blues-flavor-to-your-rhythm-with-simple-chord-embellishments/",kind:"lesson"},{id:"s5",title:"Blue Horizons: How to Mix Major and Minor Pentatonics",author:"David Hamburger",site:"Premier Guitar",year:2017,url:"https://www.premierguitar.com/articles/25911-blue-horizons-how-to-mix-major-and-minor-pentatonics",kind:"lesson"},{id:"s6",title:"Blues Guitar Scales: Theory & Practical",author:"Richard Spooner",site:"Pickup Music",year:2024,url:"https://www.pickupmusic.com/blog/blues-guitar-scales",kind:"lesson"},{id:"s7",title:"Unleashing the Power of the Blues Avengers: B.B., Albert, and Freddie King",author:"Jeff Jacobson",site:"Premier Guitar",year:2024,url:"https://www.premierguitar.com/lessons/blues/the-three-kings-of-the-blues",kind:"lesson"},{id:"s8",title:"How to play blues like Albert King",author:"Leigh Fuge",site:"Guitar.com",year:2020,url:"https://guitar.com/lessons/beginner/how-to-play-blues-like-albert-king/",kind:"lesson"},{id:"s9",title:"History of the Fender Bassman",author:"Dave Hunter",site:"Vintage Guitar",year:2018,url:"https://www.vintageguitar.com/34259/history-of-the-fender-bassman/",kind:"article"},{id:"s10",title:"Get the ultimate Stevie Ray Vaughan guitar rig",author:"John Priest (Peach Guitars)",site:"Guitar.com",year:2020,url:"https://guitar.com/features/opinion-analysis/get-the-ultimate-stevie-ray-vaughan-guitar-rig/",kind:"article"},{id:"s11",title:"Albert Collins",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Albert_Collins",kind:"encyclopedia"},{id:"s12",title:"1.3: The Blues (Popular Music)",author:"Todd Smith, Western Washington University",site:"Humanities LibreTexts",year:2022,url:"https://human.libretexts.org/Courses/Western_Washington_University/Popular_Music_(Smith)/01:_Readings/1.03:_The_Blues",kind:"paper"},{id:"s13",title:"A Short Take on Chicago Blues",author:"Adam Green",site:"Perspectives on History (American Historical Association)",year:2002,url:"https://www.historians.org/perspectives-article/a-short-take-on-chicago-blues-december-2002/",kind:"article"},{id:"s14",title:"The Vocal Blues: Created in the Deep South of the United States",author:"Ed Smith",site:"Smithsonian Folkways (lesson plan)",url:"https://folkways-media.si.edu/docs/lesson_plans/FLP10028_usa_blues.pdf",kind:"lesson"}],study:[{title:"Deep Blues",kind:"book",author:"Robert Palmer",url:"https://penguinrandomhouse.com/books/323227/deep-blues-by-robert-palmer",note:"Traces the line from Mississippi Delta players to the electric Chicago bands, the history behind this course."},{title:"B.B. King – Live at the Regal",kind:"album",note:"The record the Premier Guitar lesson uses to show major and minor phrases; listen to how he leaves space and answers his own voice."},{title:"Albert King – Born Under a Bad Sign",kind:"album",note:"Wide, slow bends and few notes: a model for making every bend count."},{title:"Stevie Ray Vaughan and Double Trouble – Texas Flood",kind:"album",note:"Texas shuffles, a slow blues and a heavy-string Strat tone on one album."},{title:"Albert Collins – Ice Pickin'",kind:"album",note:"Hear what open F-minor tuning and a high capo do to a Telecaster attack."},{title:"Learn the vibrato styles of 5 giants of the blues",kind:"lesson",url:"https://www.guitarworld.com/lessons/learn-the-vibrato-styles-of-5-giants-of-the-blues",note:"Finger-vibrato drills modeled on blues players; a good follow-up to step 4."},{title:"Blues Power: Shuffling On, Shuffle Rhythm Patterns",kind:"lesson",url:"https://guitarworld.com/lessons/blues-power-shuffling-shuffle-rhythm-patterns",note:"More shuffle and boogie rhythm figures to drill alongside step 3."},{title:"Blues Guitar Lessons for Beginners: Your First 12-Bar Jam",kind:"lesson",author:"TrueFire",url:"https://truefire.com/learn/blues-guitar-lessons-for-beginners",note:"A free walk-through of the long-short shuffle feel and a boogie riff that moves up a string with each chord change."}],steps:[{id:"sound",title:"The sound: from the Delta to the Chicago club",body:"Electric blues took older acoustic blues and plugged it in. T-Bone Walker, a Texan who moved to Los Angeles, is generally seen as its first star, and Muddy Waters and John Lee Hooker followed in the 1940s.\n\nIn Chicago, players who had come north in the Great Migration needed volume for loud clubs and street corners. They switched to electric instruments and often pushed their amps into distortion, and that grit became part of the style. Muddy Waters, often called the father of Chicago blues, set the band format: electric guitar, harmonica through an amp, bass, drums and sometimes piano. Chess was the most prominent blues label of the 1950s, with Muddy Waters, Little Walter, Willie Dixon and Howlin' Wolf among its first artists.\n\nIn the late 1950s and early 1960s a new generation of West Side players, among them Otis Rush, Magic Sam and Buddy Guy, played a smoother style with more jazz in it, and Albert King and Buddy Guy made loud lead guitar the main event. Texas electric blues flourished in Austin clubs in the late 1960s and early 1970s, and Stevie Ray Vaughan became its best-known voice.\n\nIn every listen track, follow three things: the 12-bar form, the shuffle, and a lead guitar that answers the singer.",cites:["s1","s2","s13"],blocks:[{type:"callout",tone:"tip",text:"Put on one listen track and count bars out loud: 1 to 12, then start again. Once you can hear where bar 1 comes back, the rest of this course clicks into place."}]},{id:"harmony",title:"Twelve bars and dominant chords",body:'The 12-bar blues runs on three chords: I, IV and V. In A that is A, D and E. The basic cycle is four bars of I, two of IV, two of I, then V, IV, I, and a last bar of V that turns the form around to the top.\n\nTwo small changes give it more motion. The quick change (the "quick to four") moves to the IV chord in bar 2 and comes straight back. The turnaround is the V chord in bar 12, which points the ear back to bar 1.\n\nBlues players use dominant 7th chords on all three degrees, even though only the V is a dominant chord in a major key. Adding the flat seventh to a major chord makes it a dominant 7th, and Pickup Music points out that dominant 7th chords sit on the line between major and minor. Melody notes like the flat third then rub against the major third in the chord, and that rub is a big part of the sound. A 9th chord is a dominant 7th with the 9th added on top. It is a fuller color that fits anywhere the 7th does.',cites:["s3","s4","s6"],blocks:[{type:"progression",name:"Shuffle in A with a quick change",chords:"I7 IV7 I7 - IV7 - I7 - V7 IV7 I7 V7",note:"Bar 2 is the quick change and bar 12 is the turnaround. Load it as your verse."},{type:"progression",name:"Slow blues with 9th chords",chords:"I7 IV9 I7 - IV9 - I7 - V9 IV9 I7 V9",note:"Same form with 9th chords on the IV and V for a fuller sound. Play it slowly over the 12/8 groove in step 3."},{type:"shapes",title:"Dominant voicings in A",shapes:[{name:"A7",frets:"x 0 2 0 2 0"},{name:"A7 (5th fret)",frets:"5 7 5 6 5 5"},{name:"D9",frets:"x 5 4 5 5 5"},{name:"E9",frets:"x 7 6 7 7 7"},{name:"E7",frets:"0 2 0 1 0 0"}],note:"D9 and E9 use the same shape two frets apart, so the IV to V move is one slide."}]},{id:"rhythm",title:"The shuffle and the boogie",body:"The shuffle is the heartbeat of this style. Count each beat in three (1 trip let, 2 trip let) and leave out the middle note, so each pair of eighth notes falls on the first and third notes of a triplet. What is left is a long-short swing that the drums, bass and rhythm guitar all lock to.\n\nOn guitar the standard shuffle part is a boogie figure on the two lowest strings of each chord. Hold the root and rock the top note from the fifth to the sixth and back, sometimes reaching up to the flat seventh. Boogie-woogie bass lines have long been laid over the 12-bar form, and this guitar version sits right under your fretting hand.\n\nRest your picking-hand palm lightly on the saddle for a percussive palm mute and play downstrokes. Keep the long-short feel even from bar to bar.\n\nFor a slow blues, keep the same triplet grid and drop the tempo. The second groove below plays all three triplets on the ride so you can feel every one while you bend and wait.",cites:["s4","s12","s3"],blocks:[{type:"groove",groove:{id:"blues-shuffle",name:"Blues shuffle",role:"Verse",steps:12,beats:4,meter:"4/4",swing:0,t:{hh:"x.xx.xx.xx.x",sn:"...x.....x..",kk:"x.....x....."}},note:"Hi-hat on the first and last note of each triplet, snare on 2 and 4. Your boogie riff lines up with the hi-hat."},{type:"groove",groove:{id:"blues-slow-128",name:"Slow blues in 12/8",role:"Bridge & feels",steps:12,beats:4,meter:"4/4",swing:0,t:{rd:"xxxxxxxxxxxx",sn:"...x.....x..",kk:"x.....x....x"}},note:"Every triplet on the ride. Use it around 60 bpm for the slow-blues progression."},{type:"tab",id:"blues-boogie-riff",title:"Boogie shuffle in A and D",instr:"guitar",bpm:100,grid:3,tone:"blues-tweed-edge",notes:[[0,5,0,2,"pm,D"],[0,4,2,2,"pm,D"],[2,5,0,1,"pm,D"],[2,4,2,1,"pm,D"],[3,5,0,2,"pm,D"],[3,4,4,2,"pm,D"],[5,5,0,1,"pm,D"],[5,4,4,1,"pm,D"],[6,5,0,2,"pm,D"],[6,4,5,2,"pm,D"],[8,5,0,1,"pm,D"],[8,4,5,1,"pm,D"],[9,5,0,2,"pm,D"],[9,4,4,2,"pm,D"],[11,5,0,1,"pm,D"],[11,4,4,1,"pm,D"],[12,4,0,2,"pm,D"],[12,3,2,2,"pm,D"],[14,4,0,1,"pm,D"],[14,3,2,1,"pm,D"],[15,4,0,2,"pm,D"],[15,3,4,2,"pm,D"],[17,4,0,1,"pm,D"],[17,3,4,1,"pm,D"],[18,4,0,2,"pm,D"],[18,3,5,2,"pm,D"],[20,4,0,1,"pm,D"],[20,3,5,1,"pm,D"],[21,4,0,2,"pm,D"],[21,3,4,2,"pm,D"],[23,4,0,1,"pm,D"],[23,3,4,1,"pm,D"]],note:"Root plus fifth, sixth, flat seventh, sixth. Move the same shape to the E string for the V chord."},{type:"technique",id:"palm-muting",note:"A light palm mute keeps the boogie tight and leaves room for the vocal."}]},{id:"lead",title:"Bends, vibrato and the blue notes",body:"Blues lead guitar copies the voice. The blue notes are the pitches that give the blues its cry: Pickup Music names the flat fifth in the minor blues scale and the flat third in the major one, and Acoustic Guitar counts the flat seventh among them too. On guitar you get the cry with a small bend: push the flat third a little toward the major third. Pickup Music calls that minor-to-major-third bend one of the most expressive moves in the blues.\n\nMany players mix two scales. Over the I chord the major pentatonic gives you the sweet major third; over the IV chord the minor pentatonic gives you its flat seventh. Premier Guitar's lesson follows this switch through B.B. King, Buddy Guy and Freddie King, and suggests answering a minor lick with a major one.\n\nBends and vibrato carry the feeling. B.B. King's \"butterfly\" vibrato comes from quickly rotating the fretting-hand wrist, and he left plenty of space between phrases. Albert King played a right-handed Flying V flipped over for his left hand, detuned it, and pulled the strings down toward the floor to bend notes a tone and a half or two tones wide. Bend to an exact pitch first, then add vibrato once you are there.",cites:["s6","s4","s5","s7","s8"],blocks:[{type:"scale",root:"A",scale:"pentMin",view:"box",note:"Your home base over the IV chord and for tough, bluesy phrases."},{type:"scale",root:"A",scale:"pentMaj",view:"box",note:"Same notes as F# minor pentatonic. Use it to land sweetly on the I chord."},{type:"technique",id:"bends",note:"Blues uses quarter-tone curls on the flat third and whole-step or wider bends to the root and fifth."},{type:"technique",id:"vibrato",note:"Add vibrato after the bend reaches pitch, never on the way up."},{type:"tab",id:"blues-call-response",title:"Minor call, major answer",instr:"guitar",bpm:80,grid:3,tone:"blues-tweed-edge",notes:[[0,2,8,3,"b2"],[3,1,5,2,""],[5,2,8,1,""],[6,2,5,2,""],[8,3,7,1,""],[9,3,5,3,"b1"],[12,3,6,2,""],[14,2,5,1,""],[15,2,7,2,""],[17,2,5,1,""],[18,3,6,2,""],[20,3,4,1,""],[21,4,7,3,"v"]],note:"Bar 1 stays in A minor pentatonic and ends on a curled flat third. Bar 2 answers with C# and F# from the major pentatonic and lands on A with vibrato."},{type:"tab",id:"blues-slow-bends",title:"Slow-blues bends",instr:"guitar",bpm:60,grid:3,tone:"blues-texas-drive",notes:[[0,3,7,3,"b2"],[3,3,7,2,"rb2"],[5,3,5,1,""],[6,4,7,3,"v"],[9,2,5,3,"b3"],[12,1,5,2,""],[14,2,8,1,""],[15,1,8,3,"b1"],[18,1,5,6,"v"]],note:"A whole-step bend and release, then a wide minor-third bend from E to G in the style of the big-bend players. Check each bend against the fretted target note."}]},{id:"tone",title:"Tone: a hot amp and your pick hand",body:"Chicago players often got their grit by turning tube amps up until they distorted, and much of the tone still comes from that edge. The 1950s tweed Bassman, with four 10-inch speakers, was built for bass but had plenty of crossover success with guitarists, Buddy Guy among them. Vintage Guitar calls it one of the most revered tube amps ever made for guitar, and Marshall based its JTM45 on the same circuit.\n\nSet your amp so it stays fairly clean when you pick softly and growls when you dig in. Then your pick hand works like a channel switch: soft for the verse, hard for the solo.\n\nTexas players often add a pedal. Stevie Ray Vaughan used a Strat with heavy .013 to .058 strings tuned down a half step, into Fender Vibroverb and Super Reverb amps with a Tube Screamer. Albert Collins took another route: a Telecaster in open F-minor tuning with a capo high on the neck. Single coils like a Strat or Tele give more bite and twang; humbuckers on a Les Paul or ES-335 style guitar give a rounder, thicker version of the same licks.",cites:["s2","s9","s10","s11"],blocks:[{type:"tone",id:"blues-tweed-edge",name:"Tweed at the edge",kind:"electric",guitar:"Strat, Tele or ES-335 style",pickups:"Neck or middle for warmth, bridge for bite",strings:"10s or 11s",amp:"Tweed-style combo (1950s 4x10 Bassman type)",settings:{gain:6,bass:4,mid:6,treble:6,presence:5,reverb:2},pedals:["reverb"],demo:"blues-call-response",tips:["Turn the amp up until a hard pick attack starts to break up while a soft one stays nearly clean. Chicago players pushed their amps into distortion to be heard in loud rooms.","The tweed Bassman with four 10-inch speakers is the reference amp for this sound. Its late-1950s 5F6-A version is the most celebrated, and Marshall based its JTM45 on that circuit.","Start with the bass around 4 and raise it only if the tone sounds thin. A loud tube amp gets loose in the low end as it breaks up.","Use the guitar volume knob as your gain control: roll it back for rhythm, open it up for the solo."],cites:["s2","s9"],note:"Pick soft, then hard, and listen to the amp change character with your hand."},{type:"tone",id:"blues-texas-drive",name:"Texas Strat and overdrive",kind:"electric",guitar:"Stratocaster style",pickups:"Neck or middle single-coil",strings:"Heavy, 11s to 13s, tuned down a half step",amp:"Clean Fender-style combo (Vibroverb or Super Reverb type)",settings:{gain:4,bass:5,mid:6,treble:6,presence:5,reverb:3},pedals:["od","reverb"],demo:"blues-slow-bends",tips:["Stevie Ray Vaughan used .013 to .058 strings tuned down to Eb. Lighter sets are fine to start; tuning down a half step makes heavier strings easier to bend.","Put a Tube Screamer-style overdrive in front of a clean Fender-style amp. Start with the drive low and the level high so the pedal pushes the amp more than it adds fuzz of its own.","Albert King went the other way, with light .009 to .052 strings that made wide bends easier. Choose your gauge for the bends you want to play.","Albert Collins tuned to open F minor and used a capo at the 5th, 6th or 7th fret on his Telecaster. Try a capo high on the neck to hear how it changes your attack."],cites:["s10","s8","s11"],note:"Vaughan's Live at the El Mocambo setup paired two Fender amps with a Tube Screamer."}]},{id:"form",title:"Song form: around and around",body:"A blues song is usually the 12-bar form played again and again, with a verse, a solo or both on each pass. The band format of Chicago blues helped make the standard 12-bar progression the norm.\n\nThe map below starts with a four-bar intro built from the end of the form (V, IV, I, V), so the band can count in and hit bar 1 together. Then come two verses, a solo pass, a last verse and a short ending. The V chord in bar 12 is the turnaround that sends the band back to the top; at the very end, skip it and land on the I.\n\nChange the number of passes to fit your words. Give each pass its own level: a softer verse, a louder solo, a quiet pass before the last verse.",cites:["s3","s2","s14"],blocks:[{type:"form",name:"Shuffle blues map",sections:[{type:"intro",bars:4,chords:"V7 IV7 I7 V7",groove:"blues-shuffle",fill:"f-snare8"},{type:"verse",bars:12,chords:"I7 IV7 I7 - IV7 - I7 - V7 IV7 I7 V7",groove:"blues-shuffle",fill:"f-snare8"},{type:"verse",bars:12,chords:"I7 IV7 I7 - IV7 - I7 - V7 IV7 I7 V7",groove:"blues-shuffle",fill:"f-snare8"},{type:"solo",bars:12,chords:"I7 IV7 I7 - IV7 - I7 - V7 IV7 I7 V7",groove:"blues-shuffle",fill:"f-toms"},{type:"verse",bars:12,chords:"I7 IV7 I7 - IV7 - I7 - V7 IV7 I7 V7",groove:"blues-shuffle",fill:"f-snare8"},{type:"outro",bars:4,chords:"V7 IV7 I7 -",groove:"blues-shuffle",fill:"f-stop"}],note:"For a slow blues, swap the grooves for blues-slow-128 and use the 9th-chord progression."}]},{id:"lyrics",title:"Lyrics: say it twice, then answer",body:"Blues lyrics often follow an AAB shape. The singer states a line, repeats it (sometimes with a small change), then answers it with a new line that often rhymes with the first. Give each line about four bars and try to finish the words in the first two, so there is room left over.\n\nThat room is for the band. In a 12-bar verse the singer is the caller, singing from the top of each four-bar line to around the start of its third bar, and an instrumental fill responds for the rest. As the guitarist, play your answer in the gap, then get out of the way when the next line starts.\n\nYou can mirror the lyric in your note choice too. Premier Guitar's lesson suggests major pentatonic phrases for the first two lines and a minor one for the third, to match the AAB shape.\n\nWrite about one plain, specific trouble, in the way you speak.",cites:["s14","s12","s5"],blocks:[{type:"lyrics",section:"verse",prompt:"Write one 12-bar verse in AAB form about a single, specific trouble. Line A states it, line A again repeats it (change a word if you like), and line B answers or twists it and rhymes with A.",tips:["Finish each line in about two bars and leave the other two for the guitar to answer.","Use everyday speech: a name, a place, an object you can see.","Make line B the payoff: a reason, a threat, a joke or a decision.","Sing it over the shuffle before you write the next verse."]}]},{id:"together",title:"Put it together",body:"Now build a full blues in A with the pieces from this course. Load the shuffle map as your song, then work through it one layer at a time: the boogie riff under the verse, your AAB lyric on top, and a guitar answer in each gap.\n\nFor the solo pass, start in minor pentatonic over the IV chord and switch to major pentatonic as the I chord comes back. Pick two or three bends and make them perfectly in tune, with vibrato only after they arrive.\n\nRecord one take with a soft pick hand on the verses and a hard one on the solo, and listen back for the change in the amp.",cites:["s3","s4","s5","s7"],blocks:[{type:"checklist",items:["I can play the 12-bar form with the quick change and the turnaround without counting.","My boogie riff locks to the shuffle groove at 100 bpm.","I mix minor pentatonic over the IV and major pentatonic over the I.","My bends hit the target pitch before I add vibrato.","I wrote one AAB verse and left space for the guitar to answer.","My amp cleans up when I pick softly and breaks up when I dig in."]}]}]}),LEARN.course({id:"delta-blues",family:"Blues",name:"Delta and country blues",tagline:"One voice, one guitar, an open tuning and a bottleneck.",level:"Intermediate",era:"1920s to 1940s, revived in the 1960s",artists:["Charley Patton","Son House","Robert Johnson","Skip James","Mississippi Fred McDowell","Bukka White"],listen:["Charley Patton – Pony Blues","Son House – Preachin' the Blues","Robert Johnson – Kind Hearted Woman Blues","Skip James – Devil Got My Woman","Mississippi Fred McDowell – You Gotta Move","Bukka White – Parchman Farm Blues"],key:"G major",bpm:88,meter:"4/4",tuning:{name:"Open G",notes:"D2 G2 D3 G3 B3 D4"},techniques:["slide-guitar","open-tunings","travis-picking"],sources:[{id:"d1",title:"Delta blues",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Delta_Blues",kind:"encyclopedia"},{id:"d2",title:"Video Lesson: How to Play the Blues Like Charley Patton",author:"Pete Madsen",site:"Acoustic Guitar",year:2017,url:"https://acousticguitar.com/lesson-how-to-play-the-blues-like-charley-patton/",kind:"lesson"},{id:"d3",title:"Video Lesson: How to Play Like Son House",author:"Pete Madsen",site:"Acoustic Guitar",year:2018,url:"https://acousticguitar.com/video-lesson-how-to-play-like-son-house/",kind:"lesson"},{id:"d4",title:"1.3: The Blues (Popular Music)",author:"Todd Smith, Western Washington University",site:"Humanities LibreTexts",year:2022,url:"https://human.libretexts.org/Courses/Western_Washington_University/Popular_Music_(Smith)/01:_Readings/1.03:_The_Blues",kind:"paper"},{id:"d5",title:'Nehemiah Curtis "Skip" James',site:"National Park Service, Lower Mississippi Delta Region",year:2017,url:"https://www.nps.gov/locations/lowermsdeltaregion/nehemiah-curtis-skip-james.htm",kind:"article"},{id:"d6",title:"The Hill Country Blues Began With Mississippi Fred McDowell",site:"KUNC",year:2013,url:"https://www.kunc.org/music/2013-08-10/the-hill-country-blues-began-with-mississippi-fred-mcdowell",kind:"article"},{id:"d7",title:"White, Bukka",site:"Encyclopedia.com",url:"https://www.encyclopedia.com/education/news-wires-white-papers-and-books/white-bukka",kind:"encyclopedia"},{id:"d8",title:"Style Guide: Acoustic Blues Guitar",author:"Mike Cramer",site:"Premier Guitar",year:2012,url:"https://www.premierguitar.com/articles/Style_Guide_Acoustic_Blues_Guitar",kind:"lesson"},{id:"d9",title:"Resonator Guitars 101",author:"Richie Owens",site:"Premier Guitar",year:2018,url:"https://www.premierguitar.com/gear/resonator-guitars-101",kind:"article"},{id:"d10",title:"Kind Hearted Woman Blues",author:"Ethan Hein",site:"Ethan Hein (Substack)",year:2021,url:"https://ethanhein.substack.com/p/kind-hearted-woman-blues",kind:"article"},{id:"d11",title:"Robert Johnson",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Robert_Johnson",kind:"encyclopedia"},{id:"d12",title:"The Vocal Blues: Created in the Deep South of the United States",author:"Ed Smith",site:"Smithsonian Folkways (lesson plan)",url:"https://folkways-media.si.edu/docs/lesson_plans/FLP10028_usa_blues.pdf",kind:"lesson"}],study:[{title:"Deep Blues",kind:"book",author:"Robert Palmer",url:"https://penguinrandomhouse.com/books/323227/deep-blues-by-robert-palmer",note:"A readable history of the Delta players and how their music moved north."},{title:"Escaping the Delta: Robert Johnson and the Invention of the Blues",kind:"book",author:"Elijah Wald",url:"https://elijahwald.com/rjohnson.html",note:"Puts Robert Johnson in the context of what Black audiences of his time were actually buying and hearing."},{title:"Charley Patton – Screamin' and Hollerin' the Blues",kind:"album",url:"https://nodepression.org/charley-patton-screamin-and-hollerin-the-blues/",note:"The collected Patton recordings; listen for how the guitar works as a drum."},{title:"Robert Johnson – The Complete Recordings",kind:"album",note:"All 29 songs, with alternate takes that show how he shaped his odd bar lengths."},{title:"Mississippi Fred McDowell – I Do Not Play No Rock 'n' Roll",kind:"album",note:"Hill-country drone and slide; a lesson in how far one chord can go."},{title:"Monotonic Bass Patterns",kind:"lesson",author:"Andrew DuBrock",url:"https://acousticguitar.com/monotonic-bass-patterns/",note:"Clear exercises for a steady one-note thumb under a fingerpicked melody."},{title:"Acoustic blues masterclass",kind:"lesson",url:"https://www.guitarworld.com/lessons/techniques/acoustic-blues-masterclass",note:"A wider tour of acoustic blues techniques to follow this course."}],steps:[{id:"sound",title:"The sound: one voice, one guitar",body:'Delta blues is one of the earliest known blues styles. It comes from the Mississippi Delta and is a regional form of country blues. Guitar and harmonica are its main instruments, and slide guitar is its hallmark. The music was around by 1900 and was first recorded from the mid-1920s on.\n\nCharley Patton, widely considered the father of the Delta blues, began recording for Paramount in 1929 and had a hit with "Pony Blues." He sang in a loud, gravelly voice and was a flamboyant showman. Son House met Patton in 1929, and the two performed and recorded together until Patton died in 1934. Robert Johnson recorded his 29 songs for ARC in 1936 and 1937. Skip James, who grew up near Bentonia, sang in falsetto over a minor open tuning known as cross-note tuning. Bukka White played a National steel guitar with a slide. In the North Mississippi hill country, Fred McDowell built many songs on one droning chord.\n\nJohn and Alan Lomax recorded ordinary players in the field, and in the 1960s several of these musicians were rediscovered by new folk audiences. Muddy Waters, recorded by Alan Lomax in 1941, moved to Chicago and helped turn this sound electric.',cites:["d1","d2","d3","d5","d6","d7","d11"],blocks:[{type:"callout",tone:"history",text:"Skip James recorded eighteen songs for Paramount in Grafton, Wisconsin, in February 1931, then turned away from the blues after a religious conversion. He was found again in 1964, and his return, along with those of Son House and Mississippi John Hurt, helped spark the blues revival.",cites:["d5"]}]},{id:"tunings",title:"Open tunings and the one-chord drone",body:'Many slide players retune to an open tuning. In an open tuning the open strings already sound a chord, so a slide laid straight across one fret plays a whole chord and the open strings can ring as a drone underneath.\n\nSon House favored open tunings, especially open G (D G D G B D, low to high) and open D, with D minor and standard tuning now and then. Charley Patton tuned open G up a step and a half for a brighter sound. Skip James played in a minor open tuning often called cross-note tuning: the National Park Service gives it as E minor, and this course uses the same shape a step lower as open D minor (D A D F A D). Henry Stuckey, an older guitarist who lived nearby, taught him the song "Drunken Spree."\n\nThe harmony stays simple. Some songs follow a 12-bar shape that the player stretches at will, and others hardly change chord at all: Fred McDowell often skipped chord changes for a hypnotic, droning single chord. In open G the I chord is the open strings, the IV is the 5th fret and the V is the 7th fret, all under one slide.',cites:["d3","d2","d5","d6","d10"],blocks:[{type:"tuning",name:"Open G",notes:"D2 G2 D3 G3 B3 D4",note:"From standard, lower the 6th, 5th and 1st strings a whole step. Son House's main tuning.",cites:["d3"]},{type:"tuning",name:"Open D",notes:"D2 A2 D3 F#3 A3 D4",note:"From standard, lower the 6th, 2nd and 1st strings a whole step and the 3rd a half step. Another of Son House's tunings.",cites:["d3"]},{type:"tuning",name:"Open D minor",notes:"D2 A2 D3 F3 A3 D4",note:"Open D with the 3rd string a half step lower. The same minor shape as Skip James's cross-note tuning, which he played a step higher in E minor.",cites:["d5"]},{type:"progression",name:"One-chord drone",chords:"I7 - - - - - - -",note:"Eight bars on one chord. The melody, the slide and the thumb make all the movement."},{type:"progression",name:"Country blues in G",chords:"I7 - - - IV7 - I7 - V7 IV7 I7 -",note:"The usual 12 bars as a starting point. In step 6 you will stretch and shrink it to fit the words."}]},{id:"rhythm",title:"Thumb, foot and body",body:"With no drummer, the guitarist is the rhythm section. The picking-hand thumb plays the bass while the fingers pick melody and fills. In Delta and Texas styles the thumb often plays a monotone bass, repeating one note, usually the root, while Piedmont and ragtime players alternate the thumb between chord tones. Premier Guitar's style guide names Lightnin' Hopkins, Son House and Big Bill Broonzy for the monotone approach and recommends a slight palm mute and a driving feel. Charley Patton's bass lines are often almost monotonic too, with gaps where the slide takes over.\n\nMake the guitar a drum. Son House was known for snapping the bass strings: slip the thumb under the low string and pop it so it snaps back. Stomp a foot on the beat and dig the thumb in hard.\n\nThe groove below stands in for that foot, with a light knock on 2 and 4. Practice the tab against it. Keep the thumb steady as a clock, and let the fingers play looser on top.",cites:["d8","d2","d3"],blocks:[{type:"groove",groove:{id:"delta-blues-stomp",name:"Foot stomp and knock",role:"Verse",steps:12,beats:4,meter:"4/4",swing:0,t:{kk:"x..x..x..x..",rm:"...x.....x.."}},note:"Kick for the foot on every beat, cross-stick for a knock on the guitar top. Nothing else."},{type:"tab",id:"delta-blues-monotonic",title:"Monotone thumb in open G",instr:"guitar",tuning:"D2 G2 D3 G3 B3 D4",bpm:88,grid:2,ring:!0,tone:"delta-flat-top",notes:[[0,5,0,2,"P,pm"],[2,5,0,2,"P,pm"],[4,5,0,2,"P,pm"],[6,5,0,2,"P,pm"],[8,5,0,2,"P,pm"],[10,5,0,2,"P,pm"],[12,5,0,2,"P,pm"],[14,5,0,2,"P,pm"],[0,1,0,2,"M"],[1,2,0,1,"I"],[3,1,3,1,"M"],[4,2,0,2,"I"],[5,3,3,1,"I,b1"],[7,3,0,1,"I"],[8,1,5,2,"M"],[10,2,3,1,"I"],[11,1,3,1,"M"],[12,1,0,2,"M"],[13,2,0,1,"I"],[14,3,0,2,"I"]],note:"The thumb plays the open G on every beat with a light palm mute. The fingers add the flat seventh (F) and a curled flat third (Bb) on top."},{type:"technique",id:"travis-picking",note:"Alternating bass is the Piedmont cousin of the monotone thumb. Learn both: the alternating version makes the monotone one feel easy."}]},{id:"slide",title:"Bottleneck slide",body:"Slide guitar is a hallmark of Delta blues. Early players made bottlenecks by sawing the neck off a glass bottle. Bukka White played his National steel slide-style with a short metal tube. Fred McDowell started with a pocket knife, moved to a steak bone, and settled on a glass slide for a clearer tone, worn on his ring finger. Son House wore his bottleneck on his third finger and held it at a steep angle, which suits single-note lines but pulls chords out of tune.\n\nRest the slide lightly on the strings right over the fret wire, without pressing down. Mute behind it with the fingers you are not using, so the strings behind the slide stay quiet. Add vibrato by rocking the slide a little either side of the fret, and slide into notes from below, the way a singer reaches for a pitch.\n\nOpen tunings make this work. In open G the open strings give you the I chord, so you can slide a melody on the top strings while the thumb keeps hitting the low G. Many slide players use open tunings for exactly this reason: they make chords easy under a straight slide.",cites:["d1","d4","d7","d6","d3"],blocks:[{type:"technique",id:"slide-guitar",note:"Delta players often mix slide notes with fretted ones in the same phrase. Wear the slide on your ring or little finger to keep the others free."},{type:"technique",id:"open-tunings",note:"This course uses open G and open D. Keep a tuner handy: retuned strings drift for the first few minutes."},{type:"tab",id:"delta-blues-slide",title:"Slide lick in open G",instr:"guitar",tuning:"D2 G2 D3 G3 B3 D4",bpm:80,grid:3,tone:"delta-resonator",notes:[[0,5,0,3,"P"],[0,2,10,1,""],[0,1,10,1,""],[1,2,12,5,"s"],[1,1,12,5,"s,v"],[6,5,0,3,"P"],[6,3,12,2,"v"],[8,2,10,1,""],[9,2,12,3,"s,v"],[12,5,0,3,"P"],[12,1,15,2,"v"],[14,1,12,1,"s"],[15,2,12,2,""],[17,3,12,1,""],[18,5,0,3,"P"],[18,3,10,1,""],[19,3,12,2,"s,v"],[21,5,0,3,""],[21,4,0,3,""],[21,3,0,3,""]],note:"Slide up into the 12th-fret G chord, touch the flat seventh at fret 15, and finish on the open strings. The thumb keeps the low G going under it all."},{type:"tab",id:"delta-blues-drone",title:"One-chord drone in open D",instr:"guitar",tuning:"D2 A2 D3 F#3 A3 D4",bpm:96,grid:3,tone:"delta-flat-top",notes:[[0,6,0,2,"P"],[0,1,0,2,"M"],[2,2,0,1,"I"],[3,6,0,2,"P"],[3,4,3,1,"I"],[4,4,4,2,"h"],[6,6,0,2,"P"],[6,1,3,2,"M"],[8,1,0,1,"p"],[9,6,0,2,"P"],[9,2,3,1,"I"],[10,2,0,2,"p"],[12,6,0,2,"P"],[12,4,3,1,"I"],[13,4,4,2,"h"],[15,6,0,2,"P"],[15,2,0,2,"I"],[15,1,0,2,"M"],[18,6,0,2,"P"],[18,3,0,1,"I"],[19,4,3,1,"I"],[20,4,0,1,"p"],[21,6,0,3,"P"],[21,4,0,3,"I"],[21,1,0,3,"M"]],note:"The thumb never leaves the low D. Hammer the flat third (F) up to the major third (F#) and pull off the high F to the open D: the drone does the rest."}]},{id:"tone",title:"Tone: flat-tops, resonators and a hard attack",body:"This is acoustic music, and players dig in hard. Resonator guitars came out of the 1920s, built to be louder than ordinary acoustic guitars: juke joints were loud, and rural players could not afford amplifiers. Early blues players generally favored round-neck Nationals, played upright like a normal guitar with a bottleneck. Son House played a 1930s National Duolian from the 1960s on. Square-neck models, played flat on the lap with a bar, were favored by country and bluegrass pickers.\n\nA wooden flat-top gives a warm, woody tone for thumb-driven pieces. A metal-bodied resonator gives a bright, cutting bark that suits slide. Either way, most of the sound comes from your hands: dig in with the thumb, let the treble strings ring, and pick nearer the bridge when you want more snap.\n\nThe slide itself changes the color. McDowell moved from a knife and a bone to glass because glass gave him a clearer tone, and White used a short metal tube on his steel National.",cites:["d9","d3","d6","d7"],blocks:[{type:"tone",id:"delta-flat-top",name:"Flat-top thump",kind:"acoustic",guitar:"Steel-string flat-top acoustic",pickups:"Microphone in front of the guitar",strings:"Medium gauge",amp:"Acoustic, miked close",settings:{gain:1,bass:6,mid:5,treble:5,presence:4,reverb:1},pedals:[],demo:"delta-blues-monotonic",tips:["Make the thumb the loudest part of the sound. It carries the beat, so pick it firmly and let the fingers sit a little under it.","Rest the heel of your picking hand on the bass strings for a thumping monotone bass, as Premier Guitar's style guide suggests for Delta and Texas styles.","For a percussive pop, do as Son House did and snap the bass strings: hook the thumb (or the edge of a thumbpick) under the low string and let it snap back.","Retune and check often. Dropping strings into an open tuning changes the tension and the strings take a few minutes to settle."],cites:["d8","d3"],note:"Keep reverb almost off: these records were made in plain rooms."},{type:"tone",id:"delta-resonator",name:"Steel resonator slide",kind:"acoustic",guitar:"Round-neck metal-body resonator (National style)",pickups:"Microphone in front of the cone",strings:"Medium gauge, high action for slide",amp:"Acoustic, miked close",settings:{gain:1,bass:4,mid:7,treble:7,presence:6,reverb:1},pedals:[],demo:"delta-blues-slide",tips:["Resonators were built in the 1920s to be louder than regular acoustics, so a player could cut through a noisy juke joint without an amplifier.","Choose a round-neck National-style resonator to play slide in the normal position; square-neck models are made for lap-style playing.","Bukka White played his National steel slide-style with a short metal tube. Try a metal slide on a resonator for a bright, ringing note.","Fred McDowell switched to a glass slide for a clearer tone and wore it on his ring finger. Try both materials and keep the one that sounds like your voice."],cites:["d9","d7","d6"],note:"Pick close to the cone for bark, nearer the neck for a rounder tone."}]},{id:"form",title:"Song form: the words set the length",body:"A solo player has no band to keep in step with, so the form can bend to the words. Ethan Hein's analysis of Robert Johnson's \"Kind Hearted Woman Blues\" shows a 12-bar blues in A that Johnson stretches by adding and dropping beats. He adds an extra beat to the ninth bar on every pass but the last, and the alternate take keeps several of the same odd lengths, which suggests he meant them.\n\nFred McDowell went further and often left out chord changes altogether, holding one droning chord under the whole song.\n\nSo sing first and count after. If a line needs one more bar of I before the V, add it. If a line ends early, move on early. The map below has a long verse, a regular one and a short one so you can feel the difference, and a slide break on one chord.",cites:["d10","d6"],blocks:[{type:"form",name:"Country blues map",sections:[{type:"intro",bars:2,chords:"I7 -",groove:"delta-blues-stomp",fill:""},{type:"verse",name:"Long verse",bars:13,chords:"I7 - - - IV7 - I7 - - V7 IV7 I7 -",groove:"delta-blues-stomp",fill:""},{type:"verse",bars:12,chords:"I7 - - - IV7 - I7 - V7 IV7 I7 -",groove:"delta-blues-stomp",fill:""},{type:"solo",name:"Slide break",bars:8,chords:"I7 - - - - - - -",groove:"delta-blues-stomp",fill:""},{type:"verse",name:"Short verse",bars:11,chords:"I7 - - IV7 - I7 - V7 IV7 I7 -",groove:"delta-blues-stomp",fill:""},{type:"outro",bars:2,chords:"I7 -",groove:"delta-blues-stomp",fill:""}],note:"Change the bar counts to match your own lyric once it is written."}]},{id:"lyrics",title:"Lyrics: plain words, real life",body:"Delta lyrics often use the AAB shape found across the blues: a line, the same line again (sometimes slightly changed), then a new line that answers it.\n\nThe subjects came from the singers' own lives. Bukka White served two years in Parchman Farm prison, and the 14 sides he recorded in 1940 drew on that experience. Robert Johnson's 1937 Dallas session produced much of his most somber and introspective material.\n\nWrite from your own life in the same plain way. Name real places, objects and weather. Keep each line short enough to sing in one breath, and leave a gap after it for the guitar to answer with a slide phrase.",cites:["d12","d7","d11"],blocks:[{type:"lyrics",section:"verse",prompt:"Write an AAB verse about a trip you had to make: where you were going, why you could not stay, and what you saw on the way.",tips:["Say the A line the way you would say it out loud, then repeat it with one word changed.","Let the B line answer the A line with a reason or a result.","Use one concrete picture per verse: a road, a river, a train, a door.","If a line runs long, let the bar run long too. Count it after you sing it."]}]},{id:"together",title:"Put it together",body:"Tune to open G and build a song from this course. Start with the monotone thumb and keep it going for a full minute without stopping. Then add the melody notes on top, then a verse of your own words over it.\n\nFor the break, put on the slide and play the open-G lick against the stomp groove. Try a second song in open D with the one-chord drone and no chord changes at all.\n\nLast, sing a verse and let its length decide the bar count. Load the map and edit the verse lengths to match what you sang.",cites:["d3","d8","d10"],blocks:[{type:"checklist",items:["I can retune between standard, open G and open D by ear and check with a tuner.","My thumb holds a steady monotone bass for a whole verse while the fingers play melody.","My slide notes are in tune, sitting right over the fret wire.","I can play a one-chord drone that stays interesting for eight bars.","I wrote an AAB verse and let its length set the bar count."]}]}]}),LEARN.course({id:"country",family:"Country",name:"Country guitar",tagline:"Telecaster twang, snapped strings and three chords that tell the truth.",level:"Intermediate",era:"1940s to today",artists:["Merle Travis","Chet Atkins","James Burton","Roy Nichols","Albert Lee","Brent Mason","Brad Paisley"],listen:["Merle Travis – Cannonball Rag","Chet Atkins – Mister Sandman","Ricky Nelson – Believe What You Say","Merle Haggard – Mama Tried","Albert Lee – Country Boy","Brad Paisley – Throttleneck"],key:"G major",bpm:116,meter:"4/4",techniques:["hybrid-picking","double-stops","bends","bass-root-fifth","string-muting"],sources:[{id:"c1",title:"Merle Travis",site:"Country Music Hall of Fame and Museum",url:"https://countrymusichalloffame.org/artist/merle-travis/",kind:"article"},{id:"c2",title:"James Burton",site:"Country Music Hall of Fame and Museum",url:"https://countrymusichalloffame.org/hall-of-fame/james-burton/",kind:"article"},{id:"c3",title:"On This Day in 2001, Bakersfield Sound Trailblazer and Merle Haggard Guitarist Roy Nichols Died at 68",author:"Clayton Edwards",site:"American Songwriter",year:2025,url:"https://americansongwriter.com/on-this-day-in-2001-bakersfield-sound-trailblazer-and-merle-haggard-guitarist-roy-nichols-died-at-68",kind:"article"},{id:"c4",title:"Songwriter U: Guitar 101, Chicken Pickin' Part 1",author:"Gary Talley",site:"American Songwriter",year:2016,url:"https://americansongwriter.com/songwriter-u-guitar-101-chicken-pickin-part-1/",kind:"lesson"},{id:"c5",title:"Pluck 'Em! A Crash Course in Country Guitar",author:"Troy Nelson",site:"Premier Guitar",year:2014,url:"https://www.premierguitar.com/pluck-em-a-crash-course-in-country-guitar",kind:"lesson"},{id:"c6",title:"Bending Steel with Your Bare Hands",author:"Matthew Lee",site:"Premier Guitar",year:2022,url:"https://www.premierguitar.com/lessons/country/pedal-steel-guitar-bends-lesson",kind:"lesson"},{id:"c7",title:"Nashville Number System",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Nashville_Number_System",kind:"encyclopedia"},{id:"c8",title:"Ragtime progression",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Ragtime_progression",kind:"encyclopedia"},{id:"c9",title:"A Drummer's Guide To Country",author:"Brandon Toews",site:"Drumeo",year:2023,url:"https://drumeo.com/beat/?p=18125",kind:"lesson"},{id:"c10",title:"Rig Rundown: Brent Mason",author:"John Bohlinger",site:"Premier Guitar",year:2014,url:"https://www.premierguitar.com/articles/20964-rig-rundown-brent-mason",kind:"article"},{id:"c11",title:"EHX Slap Back Echo",author:"Pete Prown",site:"Vintage Guitar",year:2023,url:"https://www.vintageguitar.com/58892/ehx-slap-back-echo/",kind:"article"},{id:"c12",title:"Harlan Howard",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Harlan_Howard",kind:"encyclopedia"}],study:[{title:"Chet Atkins and Merle Travis – The Atkins-Travis Traveling Show",kind:"album",note:"Two founders of country fingerpicking side by side; their Grammy-winning duet record."},{title:"Merle Haggard and the Strangers – Mama Tried",kind:"album",note:"Roy Nichols's Telecaster and steel-like bends at the heart of the Bakersfield sound."},{title:"Telecaster-Style Country Chops",kind:"course",url:"https://truefire.com/c2266",note:"A structured video course on Tele technique, including a chicken pickin' solo and a James Burton-inspired solo."},{title:"Twang 101: Bending Double-Stops",kind:"lesson",author:"Jason Loughlin",url:"https://www.premierguitar.com/lessons/twang-101-bending-double-stops",note:"Focused drills for keeping two-string bends in tune."},{title:"Learn 18 Country-Shred Licks With Double-Stops, Pedal-Steel Bends and Other Tricks of the Trade",kind:"lesson",url:"https://www.guitarplayer.com/lessons/learn-18-country-shred-licks-with-double-stops-pedal-steel-bends-and-other-tricks-of-the-trade",note:"A big vocabulary of licks to steal from once the basics feel easy."},{title:"Masters in Mechanics: The Albert Lee Interview",kind:"video",author:"Troy Grady",url:"https://troygrady.gumroad.com/l/mm-aleeinterview",note:"Slow-motion study of Albert Lee's picking hand, with his own explanations."},{title:"The Nashville Number System",kind:"book",author:"Chas Williams",note:"The standard guide to reading and writing number charts like a Nashville session player."}],steps:[{id:"sound",title:"The sound: thumb picking and Telecaster twang",body:"Country guitar grows from two roots. One is thumb picking. Merle Travis, from western Kentucky coal country, played syncopated bass with his thumb while his index finger picked the melody, a style he learned by following local players Ike Everly and Mose Rager. Chet Atkins, his close friend and musical disciple, recorded The Atkins-Travis Traveling Show with him.\n\nThe other root is the Telecaster. James Burton restrung his Tele with banjo strings on the top four strings so he could bend notes further, adapted Travis's picking, and developed the percussive style called chicken pickin'. He played for Ricky Nelson for about eight years and later led Elvis Presley's TCB Band. In Bakersfield, Roy Nichols's Telecaster tone and steel-like bends with Merle Haggard and the Strangers became central to that town's sound.\n\nLater players such as Albert Lee, Brent Mason and Brad Paisley are known for chicken pickin'. Listen for bright, clean notes, snapped strings, bends that sound like a pedal steel, and a rhythm part that plays bass and chord at once.",cites:["c1","c2","c3","c4"],blocks:[{type:"callout",tone:"history",text:"In 1948 Merle Travis designed a solid-body electric guitar that Paul Bigsby built. The Country Music Hall of Fame suggests it may have inspired Leo Fender's Telecaster.",cites:["c1"]}]},{id:"harmony",title:"Three chords and a number chart",body:'Songwriter Harlan Howard coined the phrase that defines a great country song as three chords and the truth. The usual three are I, IV and V: in G that is G, C and D.\n\nNashville players write chords as numbers, 1, 4 and 5, using the Nashville Number System. Neal Matthews Jr. of the Jordanaires developed it in the late 1950s to write vocal parts fast during sessions. Because the numbers show each chord\'s place in the key, one chart works in any key. A minus sign or "m" marks a minor chord, so 6- is the vi.\n\nFor turnarounds, a 2-5-1 pulls the ear home. In this course the 2 is played as a dominant chord, II7 (A7 in G). That raised-third version of the 2 is the last link of the ragtime progression (III7, VI7, II7, V7, I), a chain of dominant chords around the circle of fifths. A V7, IV, I turnaround is another simple way back to the top.',cites:["c12","c7","c8","c5"],blocks:[{type:"progression",name:"Verse on 1, 4 and 5",chords:"I - IV - V - I -",note:"As a number chart: 1 - 4 - 5 - 1 -. Same chart in any key."},{type:"progression",name:"2-5-1 turnaround",chords:"I - II7 - V7 - I -",note:"In G: G, A7, D7, G. Use the last four bars as an intro or an ending."},{type:"progression",name:"V-IV-I turnaround",chords:"I - V7 IV I -",note:"In G: G, D7, C, G. A blues-flavored way home."}]},{id:"rhythm",title:"Boom-chicka, two-beat and the train",body:"A core country rhythm on guitar is the boom-chicka: a bass note on beats 1 and 3 and a chord strum on 2 and 4. Alternate the bass between the root and another chord tone, and walk up or down to the next chord on the last beat. Keep the strums short so they click like a snare.\n\nThe drums follow the same shape. In the two-beat groove below, the kick sits under your bass notes and a cross-stick answers your strum. The train beat is one of the most common country drum beats: a steady snare pattern that imitates a moving train, heard on Johnny Cash records from the 1960s and on recent tracks by Brad Paisley and Jason Aldean. Country drummers often play it with brushes, on deep snares and kits tuned low.\n\nLock your boom-chicka to the kick. When the drummer plays the train, keep your strums short and let the snare carry the motion.",cites:["c5","c9"],blocks:[{type:"groove",groove:{id:"country-two-beat",name:"Two-beat",role:"Verse",steps:16,beats:4,meter:"4/4",swing:0,t:{hh:"x.x.x.x.x.x.x.x.",rm:"....x.......x...",kk:"x.......x......."}},note:"Kick on 1 and 3 under the bass notes, cross-stick on 2 and 4 under the strums."},{type:"groove",id:"train",note:"The train beat. Use it to lift a solo or a last chorus."},{type:"tab",id:"country-boom-chicka",title:"Boom-chicka with a walk-up",instr:"guitar",bpm:116,grid:2,notes:[[0,6,3,2,"D,pm"],[2,4,0,1,"D"],[2,3,0,1,"D"],[2,2,0,1,"D"],[2,1,3,1,"D"],[4,4,0,2,"D,pm"],[6,5,0,1,"D"],[7,5,2,1,"U"],[8,5,3,2,"D,pm"],[10,4,2,1,"D"],[10,3,0,1,"D"],[10,2,1,1,"D"],[10,1,0,1,"D"],[12,6,3,2,"D,pm"],[14,4,2,1,"D"],[14,3,0,1,"D"],[14,2,1,1,"D"],[14,1,0,1,"D"]],note:"G: root, strum, fifth, then a walk-up A, B into C. On C the bass alternates C and G."},{type:"technique",id:"bass-root-fifth",note:"Root on 1, fifth on 3 is the backbone of the boom-chicka."}]},{id:"lead",title:"Chicken pickin' and steel bends",body:"Chicken pickin' is a bright, percussive, staccato way of playing, usually on a Telecaster. Most players hold a flatpick and add the middle and ring fingers (hybrid picking); others use a thumbpick with their fingernails. Pull a string up with a finger and let it snap back against the frets for the cluck, and mix those snapped notes with muted, picked ones.\n\nCountry players also borrow from the pedal steel. Bend one string, often the G string, while other notes ring above it, and you hear the steel's moving inner voice. Playing in tune matters most: fret the target note first, then bend until you match it. Double stops (two notes at once), slid or bent, fill the space between licks.\n\nJames Burton's banjo strings let him bend notes further and keep them under control. Light strings and low action make bends easier on any guitar, and Talley's lesson says they help the snappy tone too.",cites:["c4","c5","c6","c2"],blocks:[{type:"technique",id:"hybrid-picking",note:"Pick on the low notes and muted clucks, middle and ring fingers for the snapped notes on the top strings."},{type:"technique",id:"double-stops",note:"Thirds and sixths on the top strings, often slid in from a fret below."},{type:"tab",id:"country-chicken-pickin",title:"Chicken pickin' in G",instr:"guitar",bpm:100,grid:4,tone:"country-tele-twang",notes:[[0,4,5,1,"x,D"],[1,3,4,1,"M"],[2,4,5,1,"x,U"],[3,2,3,1,"M"],[4,4,5,1,"x,D"],[5,2,5,1,"A"],[6,3,4,1,"M"],[7,2,3,1,"A"],[8,2,3,2,"M"],[8,1,3,2,"A"],[10,3,2,1,"D"],[11,3,4,1,"h"],[12,2,3,2,"M"],[14,3,4,1,"D"],[15,3,2,1,"p"],[16,4,5,2,"D"],[18,4,2,1,"D"],[19,4,4,1,"h"],[20,4,5,1,"h"],[21,3,2,1,"M"],[22,4,5,1,"x,D"],[23,3,4,1,"M"],[24,4,5,1,"x,D"],[25,2,3,1,"M"],[26,3,4,1,"D"],[27,3,2,1,"p"],[28,6,3,4,"D"],[28,4,5,4,"M"]],note:"Muted picked clucks on the D string against snapped notes from the middle and ring fingers. Ends on a G octave pinch."},{type:"tab",id:"country-steel-bends",title:"Pedal-steel bends in G",instr:"guitar",bpm:76,grid:2,tone:"country-tele-twang",notes:[[0,2,8,4,"M"],[0,3,5,4,"D,b2"],[4,1,7,4,"A"],[4,3,7,4,"D,b2"],[8,2,8,4,"M"],[8,3,7,4,"D,rb2"],[12,1,7,4,"A,v"],[12,2,8,4,"M"],[12,3,7,4,"D"]],note:"Hold the top notes still and move only the G string: C up to D under G, D up to E under B, then release back to a plain G triad."}]},{id:"tone",title:"Tone: clean, bright and a little slap",body:"A common recipe for country lead tone: a Telecaster bridge pickup, a clean amp, a compressor and a short slapback echo. Set the amp so it stays clear even when you snap the strings hard.\n\nBrent Mason's rig is a working example. His main guitar is a modified 1968 Telecaster with a Joe Glaser B-Bender, and one of his amps is a 1965 Fender Bassman. A Wampler Ego compressor is the first pedal after his wah and volume pedals. A compressor narrows the jump in level between picked notes and snapped finger notes, and helps bends sustain.\n\nSlapback is a single short echo. Its 1950s sound came from Sun Studios, and modern slapback pedals offer delay times of about 45 to 100 milliseconds, the range that recalls Nashville, Bakersfield and Austin twang. Set one repeat, no feedback, and keep the echo just behind the note.",cites:["c10","c11","c4"],blocks:[{type:"tone",id:"country-tele-twang",name:"Tele twang with slapback",kind:"electric",guitar:"Telecaster style",pickups:"Bridge single-coil",strings:"9s or 10s, low action",amp:"Clean American-style amp (Fender Bassman type)",settings:{gain:2,bass:4,mid:5,treble:7,presence:6,reverb:2,delay:4},pedals:["comp","delay","reverb"],demo:"country-chicken-pickin",tips:["Use the Tele bridge pickup for twang. Gary Talley's lesson points to low action and light strings for a snappy chicken pickin' tone.","Put the compressor early in the chain. Brent Mason runs a Wampler Ego compressor first after his wah and volume pedals.","Slapback: one repeat at roughly 45 to 100 ms, feedback at zero, and the mix low enough that it sounds like a room.","Keep plenty of clean headroom; Mason's rig includes a 1965 Fender Bassman.","For steel-style bends, James Burton used banjo strings on his top four strings. A B-Bender, like the one on Mason's Tele, raises the B string with a lever."],cites:["c4","c10","c11","c2"],note:"Snap a note hard and soft: with the compressor on, the level should barely change."}]},{id:"form",title:"Song form: verse, chorus and a hot solo",body:"This map uses a verse and chorus plan with an instrumental intro and a short guitar solo. Write it out as a number chart in four-bar lines, the way Nashville players do, and you can play it in any key the singer needs.\n\nThe song opens with the 2-5-1 turnaround as an intro, so the guitar can play a pickup lick into the first verse. The verse rides the two-beat groove on 1, 4 and 5. The chorus starts on the 4 chord and uses the 2-5 to set up the next verse. The solo switches to the train beat for energy, and the song ends with the turnaround and a stop.\n\nKeep the solo to eight bars, and quote the vocal melody in its first two bars so the listener knows where they are.",cites:["c7","c9"],blocks:[{type:"form",name:"Country song map",sections:[{type:"intro",bars:4,chords:"II7 V7 I -",groove:"country-two-beat",fill:"f-snare8"},{type:"verse",bars:16,chords:"I - IV - V - I -",groove:"country-two-beat",fill:"f-snare8"},{type:"chorus",bars:8,chords:"IV - I - II7 - V7 -",groove:"country-two-beat",fill:"f-snare8"},{type:"verse",bars:16,chords:"I - IV - V - I -",groove:"country-two-beat",fill:"f-snare8"},{type:"chorus",bars:8,chords:"IV - I - II7 - V7 -",groove:"country-two-beat",fill:"f-build"},{type:"solo",bars:8,chords:"I - IV - II7 V7 I -",groove:"train",fill:"f-snare8"},{type:"chorus",bars:8,chords:"IV - I - II7 - V7 -",groove:"country-two-beat",fill:"f-snare8"},{type:"outro",bars:4,chords:"II7 V7 I -",groove:"country-two-beat",fill:"f-stop"}],note:"Write the same map as a number chart: 1 - 4 - 5 - 1 - for the verse, 4 - 1 - 2 - 5 - for the chorus."}]},{id:"lyrics",title:"Lyrics: a story and a hook title",body:'Harlan Howard, who co-wrote "I Fall to Pieces" and wrote "Busted", is the songwriter behind "three chords and the truth". The truth is the lyric: real people, real places and a plain-spoken story.\n\nBuild your song around a title. Pick a short phrase that sounds like something a person would say, and put it at the start or end of the chorus. Then make each verse tell part of the story so the listener comes back to that line with new meaning each time. Let the second verse move the story forward in time.\n\nConcrete detail does the work: a make of truck, a town name, a time on the clock. Keep the music simple so the words come first.',cites:["c12"],blocks:[{type:"lyrics",section:"chorus",prompt:"Pick a short title phrase that sounds like something a person would say out loud, then write a four-line chorus that starts or ends with it.",tips:["Say the title in the first or last line of the chorus, and nowhere else in the verses.","Make verse one the setup and verse two the change, so the title means something new the second time.","Use one specific detail per line: a name, a place, an object.","Read it aloud: if it does not sound like speech, simplify it."]}]},{id:"together",title:"Put it together",body:"Load the country song map and build the song layer by layer. First the boom-chicka with walk-ups, locked to the two-beat groove. Then your chorus with the title in its first or last line, and two verses that move the story along.\n\nFor the intro and solo, use the chicken pickin' lick and the steel bends through the Tele tone, with compressor and slapback on. Write the whole song as a number chart and try it in a second key without changing anything but the 1.",cites:["c5","c7","c11"],blocks:[{type:"checklist",items:["My boom-chicka keeps the bass on 1 and 3 and short strums on 2 and 4.","I can play a walk-up from G to C and from C to D without losing time.","My snapped notes and muted clucks are even in volume with the compressor on.","My steel-style bends match the fretted target note.","I wrote the song as a Nashville number chart and played it in two keys.","My chorus starts or ends with the title."]}]}]}),LEARN.course({id:"bluegrass",family:"Country",name:"Bluegrass guitar",tagline:"Boom-chuck drive, a G run at every turn and flatpicked fiddle tunes.",level:"Intermediate",era:"1940s to today",artists:["Lester Flatt","Doc Watson","Clarence White","Tony Rice","Bryan Sutton","Molly Tuttle","Billy Strings"],listen:["Bill Monroe and the Blue Grass Boys – Blue Moon of Kentucky","Doc Watson – Black Mountain Rag","The Kentucky Colonels – Appalachian Swing! (album)","Tony Rice – Manzanita (album)","Molly Tuttle & Golden Highway – Crooked Tree (album)","Billy Strings – Dust in a Baggie"],key:"G major",bpm:120,meter:"4/4",techniques:["alternate-picking","bass-root-fifth","legato"],sources:[{id:"b1",title:"Bluegrass music",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Bluegrass_music",kind:"encyclopedia"},{id:"b2",title:"Flatt, Lester",site:"Encyclopedia.com",url:"https://www.encyclopedia.com/education/news-wires-white-papers-and-books/flatt-lester",kind:"encyclopedia"},{id:"b3",title:"Bluegrass Guitar Lesson: The Boom Chuck Style & Sound with Bryan Sutton",site:"ArtistWorks",year:2021,url:"https://artistworks.com/blog/bluegrass-guitar-lesson-boom-chuck-style-sound-bryan-sutton",kind:"lesson"},{id:"b4",title:'"Wildwood Flower": The Carter Family (1928)',author:"Cary O'Dell",site:"Library of Congress, National Recording Registry",url:"https://www.loc.gov/static/programs/national-recording-preservation-board/documents/WildwoodFlower.pdf",kind:"article"},{id:"b5",title:"Cross Picking 101: A Private Bluegrass Lesson with Molly Tuttle",author:"Jeffrey Pepper Rodgers",site:"Acoustic Guitar",year:2022,url:"https://acousticguitar.com/crosspicking-101-a-private-bluegrass-lesson-with-molly-tuttle-video/",kind:"lesson"},{id:"b6",title:"Flatpicking Master Class: Learn to Think and Play Like the Greats",author:"Alan Barnosky",site:"Acoustic Guitar",year:2022,url:"https://acousticguitar.com/flatpicking-master-class-from-doc-watson-to-molly-tuttle-learn-to-think-and-play-like-the-greats/",kind:"lesson"},{id:"b7",title:"Tony Rice: 1951–2020",author:"Molly Tuttle",site:"Premier Guitar",year:2020,url:"https://www.premierguitar.com/artists/guitarists/tony-rice-obituary",kind:"article"},{id:"b8",title:"Doc Watson at 100: The virtuoso guitarist brought Appalachian music to a worldwide audience and influenced generations of musicians",author:"Ted Olson",site:"The Conversation",year:2023,url:"https://theconversation.com/doc-watson-at-100-the-virtuoso-guitarist-brought-appalachian-music-to-a-worldwide-audience-and-influenced-generations-of-musicians-197387",kind:"article"},{id:"b9",title:"How to Mic a Bluegrass Band",site:"Shure",year:2014,url:"https://www.shure.com/en-US/insights/how-to-mic-a-bluegrass-band",kind:"article"},{id:"b10",title:"Frequently Asked Questions",site:"Flatpicking Guitar Magazine (flatpick.com)",url:"https://flatpick.com/category_s/2025.htm",kind:"article"},{id:"b11",title:"How to Use a Capo to Play Music in All 12 Keys",author:"Jamie Stillway",site:"Acoustic Guitar",year:2019,url:"https://acousticguitar.com/lessons-how-to-use-a-capo/",kind:"lesson"},{id:"b12",title:"Bluegrass Stories – Timeless, and Poignant",author:"Bruce Campbell",site:"California Bluegrass Association",year:2021,url:"https://californiabluegrass.org/bluegrass-stories-timeless-and-poignant/",kind:"article"}],study:[{title:"Bluegrass Guitar",kind:"book",author:"Happy Traum",note:"A long-standing method book on rhythm, runs and breaks; the Wikipedia entry on the G run draws on it."},{title:"The Kentucky Colonels – Appalachian Swing!",kind:"album",note:"Clarence White flatpicking fiddle tunes on acoustic guitar; the template for lead bluegrass guitar."},{title:"Tony Rice – Manzanita",kind:"album",note:"Regarded by many as his most distinctive solo album: clean, flowing flatpicking and great rhythm."},{title:"J.D. Crowe & the New South (1975)",kind:"album",note:"Tony Rice's breakthrough band record, with guitar solos at a time when they were still uncommon in bluegrass."},{title:"Doc Watson at 100",kind:"article",author:"Ted Olson",url:"https://theconversation.com/doc-watson-at-100-the-virtuoso-guitarist-brought-appalachian-music-to-a-worldwide-audience-and-influenced-generations-of-musicians-197387",note:"How Doc Watson took flatpicked fiddle tunes to a world audience, and who he influenced."},{title:"Flatpicking Guitar course",kind:"course",url:"https://pegheadnation.com/string-school/courses/flatpicking-guitar",note:"Step-by-step lessons on boom-chuck, G runs and fiddle-tune picking."},{title:"Molly Tuttle teaches you how to crosspick and play Wildwood Flower",kind:"lesson",url:"https://guitarworld.com/lessons/molly-tuttle-teaches-you-how-to-crosspick-and-play-wildwood-flower",note:"Crosspicking from a two-time IBMA Guitar Player of the Year."},{title:"One Guitar's Journey from Clarence White to Tony Rice to Billy Strings and Beyond",kind:"article",url:"https://nodepression.org/journal-excerpt-one-guitars-journey-from-clarence-white-to-tony-rice-to-billy-strings-and-beyond/",note:"The story of the 1935 Martin D-28 that links three generations of flatpickers."}],steps:[{id:"sound",title:"The sound: an acoustic string band",body:"Bluegrass takes its name from Bill Monroe and the Blue Grass Boys, formed in 1939. It grew in the 1940s from old-time music, Scottish and Irish folk, blues and jazz, and Monroe's 1946 to 1948 band with Lester Flatt and Earl Scruggs set its standard lineup: fiddle, five-string banjo, guitar, mandolin and upright bass, with no drums.\n\nIn that band the guitar was mostly a rhythm instrument. Flatt sang lead and played guitar, punctuating phrases with the run that now carries his name. Doc Watson helped popularize flatpicking in the early 1960s folk boom, playing fiddle tunes on the guitar with a flatpick, and Clarence White, who cut his teeth on fiddle tunes, became a key early lead guitarist. Tony Rice redefined modern flatpicking by bringing in elements of jazz and rock, and players such as Bryan Sutton, David Grier and Billy Strings came after him. Molly Tuttle, a fluid crosspicker, became the first woman to win the IBMA Guitar Player of the Year award in 2017.\n\nListen for drive: bluegrass players push the off-beats slightly ahead, which gives the music its forward lean.",cites:["b1","b2","b6","b8","b5"],blocks:[{type:"callout",tone:"history",text:'Flatt and Scruggs left Monroe in 1948 and formed the Foggy Mountain Boys. Their "Foggy Mountain Breakdown" later reached a wide audience through the film Bonnie and Clyde.',cites:["b1","b2"]}]},{id:"harmony",title:"Keys, capos and the G run",body:"Traditional bluegrass often sits in the key of G and uses the I, IV and V chords. Guitarists keep their G-position shapes and move them with a capo: for a song in Bb, capo at the third fret and play as if in G. The open strings stay available, which makes fast runs easier at bluegrass tempos. Find the key that suits the singer, then capo to it.\n\nThe G run is the guitar's signature phrase. In its fullest form in G it slides from F# to G on the sixth string, moves from A to B on the fifth and D to E on the fourth, and ends on a ringing open G string. The phrase was common in country guitar before Lester Flatt, but he used it so often to catch up at the ends of phrases with Monroe's fast band that it became known as the Lester Flatt G run. Play it at the end of a verse or chorus, as the band lands on G.",cites:["b1","b11","b2"],blocks:[{type:"progression",name:"Verse in G",chords:"I - IV - I - V -",note:"Eight bars on I, IV and V. End on the V so the next verse feels like coming home."},{type:"progression",name:"Chorus in G",chords:"IV - I - V - I -",note:"Starting the chorus on IV lifts it. The last I is your cue for a G run."},{type:"callout",tone:"tip",text:"Capo chart from G shapes: capo 2 sounds in A, capo 3 in Bb, capo 4 in B, capo 5 in C."}]},{id:"rhythm",title:"Boom-chuck: the guitar is the drum",body:"Bluegrass bands traditionally play without drums, so the rhythm guitar does much of a drummer's job. Its core pattern is the boom-chuck: the bass note of the chord on beats 1 and 3, and the rest of the chord strummed on 2 and 4. Early bluegrass often had no bass player, so the rhythm guitarist supplied the bass notes, and the strums on 2 and 4 line up with the mandolin's rhythm.\n\nAlternate the bass between the root and the fifth, and use short bass walks to move between chords: G, A, B into C, for example. Keep the strum short and crisp so the bass note stands out.\n\nThe groove below maps the band onto a drum kit so you can practice with something that feels right: the kick plays your bass notes on 1 and 3, and a cross-stick plays the mandolin's off-beat on 2 and 4.",cites:["b1","b3"],blocks:[{type:"groove",groove:{id:"bluegrass-boom-chuck-groove",name:"Boom-chuck",role:"Verse",steps:8,beats:4,meter:"4/4",swing:0,t:{rm:"..x...x.",kk:"x...x..."}},note:"Kick for the bass on 1 and 3, cross-stick for the off-beat on 2 and 4. No other drums: that is the point."},{type:"tab",id:"bluegrass-boom-chuck",title:"Boom-chuck with a walk and a G run",instr:"guitar",bpm:120,grid:2,tone:"bluegrass-dreadnought",notes:[[0,6,3,2,"D"],[2,4,0,1,"D"],[2,3,0,1,"D"],[2,2,0,1,"D"],[2,1,3,1,"D"],[4,4,0,2,"D"],[6,5,0,1,"D"],[7,5,2,1,"U"],[8,5,3,2,"D"],[10,4,2,1,"D"],[10,3,0,1,"D"],[10,2,1,1,"D"],[10,1,0,1,"D"],[12,6,3,2,"D"],[14,4,2,1,"D"],[14,3,0,1,"D"],[14,2,1,1,"D"],[14,1,0,1,"D"],[16,4,0,2,"D"],[18,3,2,1,"D"],[18,2,3,1,"D"],[18,1,2,1,"D"],[20,5,0,2,"D"],[22,3,2,1,"D"],[22,2,3,1,"D"],[22,1,2,1,"D"],[24,6,2,1,"D"],[25,6,3,1,"s"],[26,5,0,1,"D"],[27,5,2,1,"h"],[28,4,0,1,"D"],[29,4,2,1,"h"],[30,3,0,2,"D"]],note:"G, a walk A and B into C, then D, and the G run: F# slide to G, A hammer to B, D hammer to E, ringing open G."},{type:"technique",id:"bass-root-fifth",note:"Root on 1, fifth on 3, and a walk on 4 when the chord changes."}]},{id:"lead",title:"Carter-style lead, fiddle tunes and crosspicking",body:"Many early guitar breaks used the Carter Family style. From the Carter Family's first recordings in 1927, Maybelle Carter played the melody on the bass strings while strumming the rhythm on the treble strings. The Library of Congress credits this Carter Scratch with helping move the guitar from the background to a lead instrument.\n\nFiddle tunes are the flatpicker's workout. Doc Watson played them on guitar with a flatpick, and Clarence White cut his teeth on them. Alternate pick: down on the beat, up on the off-beat, and keep the hand moving even when you skip a note. Acoustic Guitar's master class recommends alternate picking to catch the bouncing pulse of a fiddle tune.\n\nCrosspicking is a guitar version of the fingerpicked banjo roll: you flatpick single notes across three adjacent strings to outline the melody and the chords. Stanley Brothers guitarist George Shuffler pioneered it in the 1950s, and Doc Watson, Clarence White and Tony Rice carried it on. Down-up and down-down-up patterns are both common. Groups of three do not divide evenly into a four-beat bar, so players often add two notes to make a 3 + 3 + 2 bar.",cites:["b4","b6","b8","b5"],blocks:[{type:"technique",id:"alternate-picking",note:"Strict down-up on eighth notes is the engine of fiddle-tune flatpicking."},{type:"technique",id:"legato",note:"The hammer-ons in the G run and the slides into melody notes come from here."},{type:"tab",id:"bluegrass-carter-lead",title:"Carter-style melody",instr:"guitar",bpm:100,grid:2,tone:"bluegrass-dreadnought",notes:[[0,6,3,1,"P"],[1,3,0,1,"I"],[1,2,0,1,"I"],[1,1,3,1,"I"],[2,5,2,1,"P"],[3,3,0,1,"I"],[3,2,0,1,"I"],[3,1,3,1,"I"],[4,4,0,1,"P"],[5,3,0,1,"I"],[5,2,0,1,"I"],[5,1,3,1,"I"],[6,4,2,1,"P"],[7,3,0,1,"I"],[7,2,0,1,"I"],[7,1,3,1,"I"],[8,5,3,1,"P"],[9,3,0,1,"I"],[9,2,1,1,"I"],[9,1,0,1,"I"],[10,4,2,1,"P"],[11,3,0,1,"I"],[11,2,1,1,"I"],[11,1,0,1,"I"],[12,4,0,1,"P"],[13,3,0,1,"I"],[13,2,0,1,"I"],[13,1,3,1,"I"],[14,5,2,1,"P"],[15,3,0,1,"I"],[15,2,0,1,"I"],[15,1,3,1,"I"],[16,6,3,2,"P"]],note:"The melody (G, B, D, E, then C, E, D, B, G) is on the bass strings; every off-beat is a brush across the top three strings. With a flatpick, play the melody with downstrokes and the brush with a quick down-up."},{type:"tab",id:"bluegrass-fiddle-line",title:"Fiddle-tune line in G",instr:"guitar",bpm:120,grid:2,tone:"bluegrass-dreadnought",notes:[[0,1,3,1,"D"],[1,1,2,1,"U"],[2,1,0,1,"D"],[3,2,3,1,"U"],[4,2,0,1,"D"],[5,2,3,1,"U"],[6,3,0,1,"D"],[7,2,0,1,"U"],[8,3,2,1,"D"],[9,2,0,1,"U"],[10,2,1,1,"D"],[11,2,3,1,"U"],[12,1,0,1,"D"],[13,2,3,1,"U"],[14,2,0,1,"D"],[15,3,2,1,"U"],[16,3,0,2,"D"]],note:"Steady eighth notes, down on the beat and up on the off-beat, in first position. Learn it slowly, then push the tempo a few bpm at a time."},{type:"tab",id:"bluegrass-crosspick-roll",title:"Crosspicking roll: G, C, D, G",instr:"guitar",bpm:100,grid:2,ring:!0,tone:"bluegrass-dreadnought",notes:[[0,3,0,3,"D"],[1,2,0,3,"D"],[2,1,3,3,"U"],[3,3,0,3,"D"],[4,2,0,3,"D"],[5,1,3,3,"U"],[6,3,0,2,"D"],[7,2,0,2,"D"],[8,3,0,3,"D"],[9,2,1,3,"D"],[10,1,0,3,"U"],[11,3,0,3,"D"],[12,2,1,3,"D"],[13,1,0,3,"U"],[14,3,0,2,"D"],[15,2,1,2,"D"],[16,3,2,3,"D"],[17,2,3,3,"D"],[18,1,2,3,"U"],[19,3,2,3,"D"],[20,2,3,3,"D"],[21,1,2,3,"U"],[22,3,2,2,"D"],[23,2,3,2,"D"],[24,3,0,3,"D"],[25,2,0,3,"D"],[26,1,3,3,"U"],[27,3,0,3,"D"],[28,2,0,3,"D"],[29,1,3,3,"U"],[30,3,0,2,"D"],[31,2,0,2,"D"]],note:"Down, down, up across the G, B and E strings, grouped 3 + 3 + 2 in each bar. Let every note ring into the next."}]},{id:"tone",title:"Tone: dreadnought, heavy pick, one microphone",body:"Martin introduced the dreadnought in the early 1930s for guitars that had to hold their own in loud string bands, and most flatpickers play a Martin D-18 or D-28 or something like it. Tony Rice played Clarence White's old 1935 Martin D-28, often called the holy grail of bluegrass guitars, and Molly Tuttle credits him with inspiring people of all ages to pick up a dreadnought and a flatpick.\n\nMuch of the tone is in the pick. The FAQ at Flatpicking Guitar Magazine's site says most flatpickers like a woody, mellow, rich tone and so use a heavier pick, while thinner picks sound brighter and thinner. Medium-gauge strings are the common choice.\n\nOn stage, early bands gathered around a single microphone and moved in and out of its pickup pattern. Step in for your break, step back for rhythm, and when several people sing, the loudest one stands back. The Del McCoury Band is known for doing this well. It takes rehearsal so nobody hits a bandmate with a headstock.",cites:["b6","b7","b10","b9"],blocks:[{type:"tone",id:"bluegrass-dreadnought",name:"Dreadnought and a heavy pick",kind:"acoustic",guitar:"Dreadnought flat-top (Martin D-28 or D-18 style)",pickups:"Microphone a short distance in front of the guitar",strings:"Medium gauge",amp:"Acoustic, one microphone",settings:{gain:1,bass:6,mid:5,treble:6,presence:5,reverb:1},pedals:[],demo:"bluegrass-fiddle-line",tips:["Pick weight shapes the tone: a heavier pick gives a woodier, rounder note and a thin one a brighter, thinner sound. The author of Flatpicking Guitar Magazine's FAQ plays about 1.0 to 1.2 mm.","Medium-gauge strings are the usual flatpicking choice because they balance playability and tone.","A dreadnought flat-top is the reference instrument: most flatpickers play a Martin D-18 or D-28 or something like it, and Tony Rice played Clarence White's 1935 D-28.","On one microphone, mix yourself: step in for a break, step back for rhythm.","Use a capo to keep open-string G shapes in other keys; the open strings make fast runs easier."],cites:["b10","b6","b7","b9","b11"],note:"Play the fiddle line with a thin pick, then a heavy one, and listen to the attack change."}]},{id:"form",title:"Song form: kickoff, verses and breaks",body:"A bluegrass song is a round of verses, choruses and instrumental breaks. One or more players take turns on the melody and improvise while the others play backup, and instrumental breakdowns are built from a series of these solos.\n\nWhen it is your turn, play the melody first, then decorate it: a slide or a hammer-on, a crosspicked bar, a G run at the end. When it is not your turn, go back to boom-chuck and play a little softer so the soloist sits on top.\n\nThe map below opens with a kickoff, an instrumental pass over the verse chords, then alternates verses and choruses with a break for the band, and ends with a short tag on V and I.",cites:["b1","b6"],blocks:[{type:"form",name:"Bluegrass song map",sections:[{type:"intro",name:"Kickoff",bars:8,chords:"I - IV - I - V -",groove:"bluegrass-boom-chuck-groove",fill:""},{type:"verse",bars:16,chords:"I - IV - I - V -",groove:"bluegrass-boom-chuck-groove",fill:""},{type:"chorus",bars:8,chords:"IV - I - V - I -",groove:"bluegrass-boom-chuck-groove",fill:""},{type:"solo",name:"Break",bars:16,chords:"I - IV - I - V -",groove:"bluegrass-boom-chuck-groove",fill:""},{type:"verse",bars:16,chords:"I - IV - I - V -",groove:"bluegrass-boom-chuck-groove",fill:""},{type:"chorus",bars:8,chords:"IV - I - V - I -",groove:"bluegrass-boom-chuck-groove",fill:""},{type:"outro",name:"Tag",bars:4,chords:"V - I -",groove:"bluegrass-boom-chuck-groove",fill:""}],note:"Add a second break for another instrument, or a fiddle-tune break in the middle."}]},{id:"lyrics",title:"Lyrics: home, work, faith and loss",body:"Bluegrass songs often tell stories from everyday rural life. Common subjects include lost love, family trouble and the hard economic life of Appalachia; some songs protest the coal industry, and railroad ballads are popular. Gospel songs are a regular part of the repertoire, and Monroe tied the music to Methodist, Holiness and Baptist traditions.\n\nThe California Bluegrass Association's welcome column picks out four lasting themes: unrequited love, murder ballads, loss and death in the family, and love of home, where someone who left the old homestead longs to go back and finds it never quite the same.\n\nWrite in plain words with clear pictures: a porch, a mine, a church on a hill. Bluegrass singers often stack two to four harmony parts, so keep chorus lines short and easy to sing together.",cites:["b1","b12"],blocks:[{type:"lyrics",section:"verse",prompt:"Write a verse about leaving home for work: the place you left, the work you found, and the one thing you hold on to (a person, a prayer or a promise).",tips:["Name the home place and the work place: a hollow, a mill town, a rail yard.","Let one line point back home and one line point to faith or hope.","Keep each line to one breath at a quick tempo.","Save the loss for the last line of the verse so it lands as the band hits the chorus."]}]},{id:"together",title:"Put it together",body:"Load the bluegrass map and build the song in order. Start with boom-chuck against the groove until the bass walks feel automatic, and finish every chorus with a G run.\n\nFor the kickoff, play the Carter-style melody over the verse chords, then try the same spot as a flatpicked line with alternate picking. Use the crosspicking roll to fill a bar of G in your break. Write a verse about home and work and sing it while you play rhythm.\n\nIf your voice wants another key, capo up and keep every shape the same.",cites:["b3","b2","b11"],blocks:[{type:"checklist",items:["My boom-chuck keeps the bass on 1 and 3 and a short strum on 2 and 4.","I can play the G run cleanly at 120 bpm and land on the G chord.","I can play a Carter-style melody on the bass strings with brushes in between.","My alternate picking stays down-up through the whole fiddle line.","I can crosspick the roll over G, C and D while the notes ring.","I wrote a verse about home, work, faith or loss and sang it over my rhythm."]}]}]});